mutants.new:
{(() => {
  const fire = () => regenNfos.mutate({ overwrite: true, dry_run: false });
  return (
    <Button variant="destructive" disabled={busy} onClick={fire}>
      Regen missing NFOs
    </Button>
  );
})()}

mutants.old:
return typeof record.body === "object"
  && record.body !== null
  && (record.body as Record<string, unknown>).overwrite === true;
